import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import api from '../../../services/api';

function DepartmentManageEvaluations() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [evaluations, setEvaluations] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [courses, setCourses] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [creating, setCreating] = useState(false);
  const [form, setForm] = useState({
    course_id: '',
    teacher_id: '',
    academic_year: '',
    semester: '',
    year_level: '',
    opened_at: '',
    closed_at: '',
  });

  const loadEvaluations = async () => {
    setLoading(true);
    setError('');
    try {
      const res = await api.get(`/evaluations?department_id=${id}`);
      setEvaluations(res.data?.data || res.data || []);
    } catch (e) {
      setError('Failed to load evaluations');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadEvaluations(); }, [id]);

  useEffect(() => {
    const loadMeta = async () => {
      try {
        const [crs, tch] = await Promise.all([
          api.get('/courses'),
          api.get('/teachers'),
        ]);
        const courseList = (crs.data?.data || crs.data || []).filter(c => (c.department?.id || c.department_id) === Number(id));
        const teacherList = (tch.data?.data || tch.data || []).filter(t => (t.department_id ?? t.department?.id) === Number(id));
        setCourses(courseList);
        setTeachers(teacherList);
      } catch (e) {
        // Ignore meta load errors
      }
    };
    loadMeta();
  }, [id]);

  const resetForm = () => setForm({ course_id: '', teacher_id: '', academic_year: '', semester: '', year_level: '', opened_at: '', closed_at: '' });

  const startCreate = () => { resetForm(); setCreating(true); setMessage(''); setError(''); };
  const cancelCreate = () => { setCreating(false); };

  const submitCreate = async () => {
    setError('');
    setMessage('');
    try {
      const payload = { ...form };
      if (!payload.course_id || !payload.teacher_id || !payload.academic_year || !payload.semester || !payload.year_level || !payload.opened_at) {
        setError('Please fill in all required fields');
        return;
      }
      const res = await api.post('/evaluations', payload);
      setMessage('Evaluation created');
      setCreating(false);
      await loadEvaluations();
    } catch (e) {
      setError(e?.response?.data?.message || 'Failed to create evaluation');
    }
  };

  const deleteEvaluation = async (evaluationId) => {
    if (!window.confirm('Delete this evaluation? This will remove related feedbacks.')) return;
    try {
      await api.delete(`/evaluations/${evaluationId}`);
      setMessage('Evaluation deleted');
      await loadEvaluations();
    } catch (e) {
      setError(e?.response?.data?.message || 'Failed to delete evaluation');
    }
  };

  const editFormQuestions = (evaluationId) => {
    try {
      if (typeof window !== 'undefined') {
        localStorage.setItem('deptSelectedEvalId', String(evaluationId));
      }
    } catch {}
    navigate(`/department/${id}/evaluations`);
  };

  const columns = useMemo(() => ([
    { key: 'id', label: 'ID' },
    { key: 'course', label: 'Course' },
    { key: 'teacher', label: 'Teacher' },
    { key: 'year_level', label: 'Year' },
    { key: 'semester', label: 'Semester' },
    { key: 'opened_at', label: 'Opened' },
    { key: 'closed_at', label: 'Closed' },
    { key: 'actions', label: 'Actions' },
  ]), []);

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
        <h2>Manage Evaluations</h2>
        <button className="btn btn-primary" onClick={startCreate}>Add Evaluation</button>
      </div>
      {message && <div className="alert alert-success" role="status">{message}</div>}
      {error && <div className="alert alert-error" role="alert">{error}</div>}
      {loading ? (
        <p>Loading…</p>
      ) : (
        <div className="table" role="table" aria-label="Evaluations list">
          <div className="table-row table-header" role="row">
            {columns.map(c => (
              <div key={c.key} className="table-cell" role="columnheader">{c.label}</div>
            ))}
          </div>
          {(evaluations || []).map(ev => (
            <div key={ev.id} className="table-row" role="row">
              <div className="table-cell" role="cell">{ev.id}</div>
              <div className="table-cell" role="cell">{ev.course?.title || ev.course?.name || '—'}</div>
              <div className="table-cell" role="cell">{ev.teacher?.name || '—'}</div>
              <div className="table-cell" role="cell">{ev.year_level ?? '—'}</div>
              <div className="table-cell" role="cell">{ev.semester}</div>
              <div className="table-cell" role="cell">{ev.opened_at}</div>
              <div className="table-cell" role="cell">{ev.closed_at || '—'}</div>
              <div className="table-cell" role="cell" style={{ display: 'flex', gap: 8 }}>
                <button className="btn btn-ghost" onClick={() => editFormQuestions(ev.id)}>Edit Form</button>
                <button className="btn btn-danger" onClick={() => deleteEvaluation(ev.id)}>Delete</button>
              </div>
            </div>
          ))}
        </div>
      )}

      {creating && (
        <div className="modal">
          <div className="modal-content">
            <h3>Create Evaluation</h3>
            <div className="grid" style={{ gridTemplateColumns: '1fr 1fr', gap: 12 }}>
              <label>
                Course
                <select value={form.course_id} onChange={e => setForm(f => ({ ...f, course_id: e.target.value }))}>
                  <option value="">Select course</option>
                  {courses.map(c => (
                    <option key={c.id} value={c.id}>{c.title || c.name} ({c.code})</option>
                  ))}
                </select>
              </label>
              <label>
                Teacher
                <select value={form.teacher_id} onChange={e => setForm(f => ({ ...f, teacher_id: e.target.value }))}>
                  <option value="">Select teacher</option>
                  {teachers.map(t => (
                    <option key={t.id} value={t.id}>{t.name}</option>
                  ))}
                </select>
              </label>
              <label>
                Academic Year
                <input type="text" placeholder="2025/26" value={form.academic_year} onChange={e => setForm(f => ({ ...f, academic_year: e.target.value }))} />
              </label>
              <label>
                Semester
                <input type="text" placeholder="1 or 2" value={form.semester} onChange={e => setForm(f => ({ ...f, semester: e.target.value }))} />
              </label>
              <label>
                Year Level
                <input type="number" min="1" max="6" value={form.year_level} onChange={e => setForm(f => ({ ...f, year_level: e.target.value }))} />
              </label>
              <label>
                Opened At
                <input type="date" value={form.opened_at} onChange={e => setForm(f => ({ ...f, opened_at: e.target.value }))} />
              </label>
              <label>
                Closed At (optional)
                <input type="date" value={form.closed_at} onChange={e => setForm(f => ({ ...f, closed_at: e.target.value }))} />
              </label>
            </div>
            <div style={{ display: 'flex', gap: 8, marginTop: 16 }}>
              <button className="btn btn-primary" onClick={submitCreate}>Create</button>
              <button className="btn btn-ghost" onClick={cancelCreate}>Cancel</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default DepartmentManageEvaluations;